314	/// Parse the sole JSON record on stdout, enforcing the observable contract:
315	/// exactly one line, exactly the six documented keys in documented order,
316	/// format 1, fixed algorithm name, valid version range, 64 lowercase hex tag.
317	fn parse_single_record(stdout: &[u8]) -> Record {
318	    let text = std::str::from_utf8(stdout).expect("stdout must be valid UTF-8");
319	    assert!(text.starts_with('{'), "stdout must start with the JSON object");
320	    let body = text
321	        .strip_suffix('\n')
322	        .expect("stdout must end with exactly one newline");
323	    assert!(!body.is_empty(), "stdout must contain one JSON record");
324	    assert!(!body.contains('\n'), "stdout must contain exactly one line");
325	    assert!(!body.ends_with('\r'), "line must not carry a carriage return");
326	
327	    let raw = Json::parse(body);
328	    let keys: Vec<&str> = raw.as_object().iter().map(|(k, _)| k.as_str()).collect();
329	    assert_eq!(
330	        keys,
331	        vec![
332	            "format",
333	            "algorithm",
334	            "key_id",
335	            "key_version",
336	            "fields",
337	            "tag"
338	        ],
339	        "record field structure must stay compatible"
340	    );
341	
342	    let fields = raw
343	        .get("fields")
344	        .as_array()
345	        .iter()
346	        .map(|v| v.as_str().to_string())
347	        .collect();
348	
349	    let rec = Record {
350	        format: raw.get("format").as_i64(),
351	        algorithm: raw.get("algorithm").as_str().to_string(),
352	        key_id: raw.get("key_id").as_str().to_string(),
353	        key_version: raw.get("key_version").as_i64(),
354	        fields,
355	        tag: raw.get("tag").as_str().to_string(),
356	        raw,
357	    };
358	
359	    assert_eq!(rec.format, 1, "format must always be 1");
360	    assert_eq!(rec.algorithm, "HMAC-SHA256");
361	    assert!(
362	        (1..=u32::MAX as i64).contains(&rec.key_version),
363	        "key_version out of range: {}",
364	        rec.key_version
365	    );
366	    assert_eq!(rec.tag.len(), 64, "tag must be 64 hex characters");
367	    assert!(
368	        rec.tag
369	            .bytes()
370	            .all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')),
371	        "tag must be lowercase hex, got {}",
372	        rec.tag
373	    );
374	    rec
375	}
