566	/// Run the same signing twice and return both records' parsed form plus the
567	/// exact stdout bytes, for determinism comparisons.
568	fn sign_twice(key: &str, key_id: &str, version: &str, fields: &[&str]) -> (Record, Record, Vec<u8>, Vec<u8>) {
569	    let out1 = run_sign(key, key_id, version, fields);
570	    let out2 = run_sign(key, key_id, version, fields);
571	    assert_eq!(out1.status.code(), Some(0));
572	    assert_eq!(out2.status.code(), Some(0));
573	    assert!(out1.stderr.is_empty() && out2.stderr.is_empty());
574	    (
575	        parse_single_record(&out1.stdout),
576	        parse_single_record(&out2.stdout),
577	        out1.stdout,
578	        out2.stdout,
579	    )
580	}
