let mut i = 0;
while i < args.len() {
    let arg = &args[i];
    // Support both "--opt value" and "--opt=value" forms.
    let (name, inline_value) = match arg.split_once('=') {
        Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
        _ => (arg.as_str(), None),
    };
    let take_value = |i: &mut usize| -> Result<String, String> {
        if let Some(v) = inline_value {
            return Ok(v);
        }
        *i += 1;
        args.get(*i)
            .cloned()
            .ok_or_else(|| format!("option {name} requires a value"))
    };
    match name {
        "--key" => {
            let v = take_value(&mut i)?;
            set_once(&mut key, "--key", v)?;
        }
        "--key-id" => {
            let v = take_value(&mut i)?;
            set_once(&mut key_id, "--key-id", v)?;
        }
        "--key-version" => {
            let v = take_value(&mut i)?;
            set_once(&mut key_version, "--key-version", v)?;
        }
        "--field" => {
            let v = take_value(&mut i)?;
            fields.push(v);
        }
        // Do not name the offending token: it can be a shifted secret
        // (e.g. `--key-id --key SECRET ...` swallows the flag and leaves
        // the secret as a positional). Point at the known options.
        _ => {
            return Err(format!(
                "unrecognized option or argument; expected one of: {KNOWN_OPTIONS}"
            ));
        }
    }
    i += 1;
}
